#[test]
fn test_an_enlarged_raster_keeps_flat_ink_and_edges() {
    let s: &crate::port::BitmapSet = &crate::port::BitmapSet::new();
    let src: &crate::port::Bitmap = crate::port::bms_put(s, 7, 4, 3, 1);
    let wt: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let mut y: i32 = 0;
    let mut x: i32 = 0;
    // left half black (0), right half white (255); the third row all 120
    while y < 3 {
        x = 0;
        while x < 4 {
            if y == 2 {
                crate::port::bitmap_set_u8(src, x, y, 0, 120);
            } else if x >= 2 {
                crate::port::bitmap_set_u8(src, x, y, 0, 255);
            } else {
                crate::port::bitmap_set_u8(src, x, y, 0, 0);
            }
            x += 1;
        }
        y += 1;
    }
    crate::testport::assert_eq(crate::port::bms_has(s, 9), 0, "not made yet");
    up_make(s, 9, 10, src, 3, wt);
    crate::testport::assert_eq(crate::port::bms_has(s, 9), 1, "made");
    let big: &crate::port::Bitmap = crate::port::bms_get(s, 9);
    crate::testport::assert_eq(crate::port::bitmap_w(big), 12, "3 times as wide");
    crate::testport::assert_eq(crate::port::bitmap_h(big), 9, "and as high");
    crate::testport::assert_eq(crate::port::bitmap_channels(big), 1, "one channel");
    crate::testport::assert_eq(crate::port::bitmap_u8(big, 0, 7, 0), 120, "a flat row stays flat: its left");
    crate::testport::assert_eq(crate::port::bitmap_u8(big, 11, 7, 0), 120, "and its right");
    crate::testport::assert_eq(crate::port::bitmap_u8(big, 6, 7, 0), 120, "and its middle");
    x = 1;
    while x < 12 {
        crate::testport::assert_that(crate::port::bitmap_u8(big, x, 0, 0) >= crate::port::bitmap_u8(big, x - 1, 0, 0), "an edge rises left to right: no ring below the black");
        x += 1;
    }
    crate::testport::assert_eq(crate::port::bitmap_u8(big, 0, 0, 0), 0, "black at the left");
    crate::testport::assert_eq(crate::port::bitmap_u8(big, 11, 0, 0), 255, "white at the right");
}
#[test]
fn test_receipt_quality_uses_confident_alphanumeric_bearing_token_length() {
    let ans: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let at: i32 = an_ocr(ans, 31);
    let low: i32 = an_ocr_word(ans, at, 0, 0, 10, 10, 499, 0, 0);
    an_ocr_cp(ans, low, 65);
    let edge: i32 = an_ocr_word(ans, at, 10, 0, 10, 10, 500, 0, 0);
    an_ocr_cp(ans, edge, 57);
    let dots: i32 = an_ocr_word(ans, at, 20, 0, 10, 10, 999, 0, 0);
    an_ocr_cp(ans, dots, 46);
    an_ocr_cp(ans, dots, 46);
    an_ocr_cp(ans, dots, 46);
    let token: i32 = an_ocr_word(ans, at, 30, 0, 10, 10, 800, 0, 0);
    an_ocr_cp(ans, token, 36);
    an_ocr_cp(ans, token, 65);
    an_ocr_end(ans, at);
    crate::testport::assert_eq(up_receipt_score(ans, at), 131, "conf49 is ignored, conf50 is included, punctuation alone cannot vote; the full alphanumeric-bearing token contributes");
}
